CREATE OR REPLACE FUNCTION public.record_game_activity(p_game_id text, p_event text, p_visitor_hash text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ BEGIN IF p_event NOT IN ('open','play') OR length(p_game_id) NOT BETWEEN 1 AND 160 OR p_visitor_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid activity'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_visitor_hash,0)); IF (SELECT count(*) FROM public.game_activity WHERE visitor_hash=p_visitor_hash AND created_at > now()-interval '1 hour') >= 120 THEN RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM public.game_activity WHERE visitor_hash=p_visitor_hash AND game_id=p_game_id AND event_type=p_event AND created_at > now()-interval '30 minutes') THEN INSERT INTO public.game_activity(game_id,event_type,visitor_hash) VALUES(p_game_id,p_event,p_visitor_hash); END IF; DELETE FROM public.game_activity WHERE created_at < now()-interval '60 days'; END $$;
REVOKE ALL ON FUNCTION public.record_game_activity(text,text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_game_activity(text,text,text) TO service_role;